function generalTimer(t){endDates[t],startDates[t];const o=(endDates[t]-Date.now())/1e3;var n=Math.floor(o/24/60/60),l=Math.floor(o-86400*n),a=Math.floor(l/3600),e=Math.floor(l-3600*a),s=Math.floor(e/60),d=o%60;function r(t){const o=Math.floor(t);return o<10?"0"+o:o}let c=parseInt(r(n));c>0?$("#countdown-days-"+t).html(c+"<small>d</small>"):$("#countdown-days-"+t),$("#countdown-hours-"+t).html(r(a)),$("#countdown-mins-"+t).html(r(s)),$("#countdown-secs-"+t).html(r(d)),o<=0&&(clearInterval(countdownTimers[t]),$("#countdown-days-"+t).html("--"),$("#countdown-hours-"+t).html("--"),$("#countdown-mins-"+t).html("--"),$("#countdown-secs-"+t).html("--"))}var countdownTimers={};for(lotIdIndex in startDates)countdownTimers[lotIdIndex]=setInterval("generalTimer("+lotIdIndex+")",1e3);